journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_id(value):
    return isinstance(value, str) and bool(value)


def _same(record, other):
    return (record["id"] == other["id"]
            and record["component"] == other["component"]
            and record["units"] == other["units"]
            and record["depends_on"] == other["depends_on"])


def read_changes(records):
    """Validate change records, then collapse duplicates.

    Equality covers id, component, units and the set of dependencies. A second
    record for an id that is not identical is a conflict.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not _is_id(row.get("id"))
                or not _is_id(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on", [])
        if not isinstance(depends_on, list) or not all(_is_id(item) for item in depends_on):
            raise JournalError("invalid-change")
        record = {"id": row["id"], "component": row["component"],
                  "units": row["units"], "depends_on": sorted(set(depends_on))}
        for seen in changes:
            if seen["id"] == record["id"]:
                if not _same(seen, record):
                    raise JournalError("conflicting-change")
                break
        else:
            changes.append(record)
    return changes


def read_ids(value, default=()):
    """Validate an optional list of change IDs such as `applied` or `retain`."""
    if value is None:
        return list(default)
    if not isinstance(value, list) or not all(_is_id(item) for item in value):
        raise JournalError("invalid-change")
    return sorted(set(value))

