"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_changes, read_ids
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes, applied):
    """Full execution order: unapplied first by (batch, id), then applied."""
    by_id = {record["id"]: record for record in changes}
    unknown = applied.union(*(record["depends_on"] for record in changes)) - by_id.keys()
    if unknown:
        raise JournalError("unknown-dependency")

    outstanding = {}
    children = {record["id"]: [] for record in changes}
    for record in changes:
        if record["id"] in applied:
            continue
        pending = set(record["depends_on"]) - applied
        outstanding[record["id"]] = len(pending)
        for dependency in pending:
            children[dependency].append(record["id"])

    ready = []
    for record in changes:
        if record["id"] in applied:
            continue
        if outstanding[record["id"]] == 0:
            heapq.heappush(ready, record["id"])

    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for child in children[current]:
            outstanding[child] -= 1
            if outstanding[child] == 0:
                heapq.heappush(ready, child)

    if len(order) != len(changes) - len(applied & by_id.keys()):
        raise JournalError("dependency-cycle")
    return order + [record["id"] for record in changes if record["id"] in applied]


def _read_retain(value):
    """G2: a malformed retain list is reported as `invalid-retain`."""
    try:
        return set(read_ids(value))
    except JournalError:
        raise JournalError("invalid-retain") from None


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = set(read_ids(request.get("applied")))
        by_id = {record["id"]: record for record in changes}
        order = _topological_order(changes, applied)
        retain = _read_retain(request.get("retain")) if request["action"] == "rollback" else set()
        if not retain <= applied or not retain <= by_id.keys():
            raise JournalError("invalid-retain")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if request["action"] == "plan":
        # Applied entries satisfy dependencies but are not emitted again.
        actions = [change for change in order if change not in applied]
        units = sum(by_id[change]["units"] for change in actions)
        if units > budget:
            return failure("budget-exceeded")
        return {"status": "ok", "actions": actions, "units": units}

    # G2: retained changes also keep every applied dependency they transitively need.
    kept = set(retain)
    pending = list(retain)
    while pending:
        for dependency in by_id[pending.pop()]["depends_on"]:
            if dependency in applied and dependency not in kept:
                kept.add(dependency)
                pending.append(dependency)
    actions = [change for change in reversed(order) if change in applied and change not in kept]
    return {"status": "ok", "actions": actions,
            "units": sum(by_id[change]["units"] for change in actions)}

