"""Compose policy and journal data into a plan.

Planner owns graph construction, ordering, budget decisions and result
assembly.  Import direction: planner -> journal, policy (never the reverse),
so validation always happens before any ordering work.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def _check_edges(changes):
    """Reject dependencies that name no known change.

    `changes` are already deduplicated, so the ID set is final.  A missing
    target means the caller described a graph this service cannot order;
    SPEC maps that to `unknown-dependency`.
    """
    known = {change["id"] for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")


def _topological_order(changes):
    """Return every change ID in deterministic dependency order.

    Among all currently eligible changes (every dependency already emitted)
    the lexicographically smallest ID goes first.  The heap gives that order
    without re-sorting, and the emitted count detects cycles: if fewer IDs come
    out than went in, some group never became eligible, which is exactly a
    cycle.  Eligibility ignores the `applied` journal on purpose; replay only
    filters the final sequence, so ordering stays stable for both actions.
    """
    total = len(changes)
    units_by_id = {change["id"]: change["units"] for change in changes}
    indegree = {change["id"]: len(set(change["depends_on"])) for change in changes}
    children = {change["id"]: [] for change in changes}
    for change in changes:
        # A dependency listed twice is one edge; the indegree above is
        # deduplicated on the same basis.
        for target in set(change["depends_on"]):
            children[target].append(change["id"])

    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for child in children[current]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != total:
        raise JournalError("dependency-cycle")
    return order, units_by_id


def plan(request):
    """Validate, order and assemble one result object.

    Never raises: every domain problem becomes a failure envelope so the
    transport can print a single JSON object for any request.
    """
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy runs first so a disallowed operation emits no partial actions.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        known_ids = {change["id"] for change in changes}
        applied = read_applied(request.get("applied"), known_ids)
        _check_edges(changes)
        order, units_by_id = _topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    action = request["action"]
    if action == "plan":
        # Already applied entries satisfy their dependents but cost nothing
        # now, so only the units actually emitted are counted against budget.
        emitted = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
        if units > budget:
            return failure("budget-exceeded")
        return _success(emitted, units)

    # rollback: reverse of the full topological order, applied entries only.
    # Reverting a dependency before its dependents would be unsafe, hence the
    # reversal.  budget is validated by policy but deliberately does not cap
    # rollback: an operator must be able to unwind everything already released
    # even with no remaining allowance.
    emitted = [change_id for change_id in reversed(order) if change_id in applied]
    units = sum(units_by_id[change_id] for change_id in emitted)
    return _success(emitted, units)

