    not report as applied is likewise out of scope.  Iterating to a fixpoint
    rather than recursing keeps the walk safe if the graph is deep, and the
    visited set makes a cycle impossible to revisit (cycles are already rejected
    by `_topological_order` before this runs).
    """
    dependencies = {change["id"]: change["depends_on"] for change in changes}
    closure = set(retained)
    pending = list(retained)
    while pending:
        current = pending.pop()
        for target in dependencies.get(current, ()):
            if target in closure or target not in applied or target not in dependencies:
                continue
            closure.add(target)
            pending.append(target)
    return closure


def plan(request):
    """Validate, order and assemble one result object.

    Never raises: every domain problem becomes a failure envelope so the
    transport can print a single JSON object for any request.
    """
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy runs first so a disallowed operation emits no partial actions.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        known_ids = {change["id"] for change in changes}
        applied = read_applied(request.get("applied"), known_ids)
        _check_edges(changes)
        order, units_by_id = _topological_order(changes)
        # G2: `retain` is a staging-rollback field.  Parsing it here -- after
        # the journal is known and before any output -- means a bad retain list
        # fails the whole request with `invalid-retain` and never a partial
        # rollback.  A `plan` request ignores the key entirely, so G1 plan
        # behaviour (and G1 requests that happen to carry `retain`) is unchanged.
        if request["action"] == "rollback":
            retained = read_retain(request.get("retain"), applied, known_ids)
        else:
            retained = set()
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    action = request["action"]
    if action == "plan":
        # Already applied entries satisfy their dependents but cost nothing
        # now, so only the units actually emitted are counted against budget.
        # G2 caps the effective budget at `plan_limit` (staging plan -> at most
        # 3) while leaving the request budget validated and unchanged.
        emitted = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
        if units > plan_limit(budget, action):
            return failure("budget-exceeded")
        return _success(emitted, units)

    # rollback: reverse of the full topological order, applied entries only.
    # Reverting a dependency before its dependents would be unsafe, hence the
    # reversal.  budget is validated by policy but deliberately does not cap
    # rollback: an operator must be able to unwind everything already released
    # even with no remaining allowance.
    #
    # G2: retained changes and the applied dependencies they transitively need
    # are dropped from the output.  Dropping rather than reordering keeps the
    # relative order of everything still emitted exactly as the G1 reverse
    # order, so a request without `retain` is byte-for-byte unchanged.
    if retained:
        keep = _retained_closure(retained, changes, applied)
    else:
        keep = set()
    emitted = [
        change_id
        for change_id in reversed(order)
        if change_id in applied and change_id not in keep
    ]
    units = sum(units_by_id[change_id] for change_id in emitted)
    return _success(emitted, units)

