"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, select


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(ids, units):
    return {"status": "ok", "actions": ids, "units": units}


def dependency_order(changes, applied):
    """Return the full deterministic topological order of change IDs.

    Missing targets and unknown persisted IDs fail with ``unknown-dependency``;
    a cycle anywhere fails with ``dependency-cycle``. Among currently eligible
    changes the lexicographically smallest ID goes first.
    """
    ids = {change["id"] for change in changes}
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in ids:
                raise JournalError("unknown-dependency")
    for dep in applied:
        if dep not in ids:
            raise JournalError("unknown-dependency")

    children = {cid: [] for cid in ids}
    pending = {}
    for change in changes:
        cid = change["id"]
        pending[cid] = len(change["depends_on"])
        for dep in change["depends_on"]:
            children[dep].append(cid)

    ready = [cid for cid, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for child in children[cid]:
            pending[child] -= 1
            if pending[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(ids):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = select(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        order = dependency_order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units = {change["id"]: change["units"] for change in changes}
    if action == "plan":
        emitted = [cid for cid in order if cid not in applied]
        total = sum(units[cid] for cid in emitted)
        if total > budget:
            return failure("budget-exceeded")
        return success(emitted, total)
    emitted = [cid for cid in reversed(order) if cid in applied]
    return success(emitted, sum(units[cid] for cid in emitted))

