"""Normalize release records at the input boundary.

This layer owns request shape, change identity and replay. It runs before any
graph work in planner.py so that deduplication and the persisted ``applied``
journal are already settled when ordering and budgeting happen: budget must be
measured on emitted units after collapse, and applied entries must satisfy
dependencies without consuming budget.
"""


class JournalError(ValueError):
    """Carries one of the SPEC error codes verbatim as the exception text."""

    pass


def _is_id(value):
    return isinstance(value, str) and value != ""


def _is_int(value):
    # ``type(...) is int`` rejects booleans, which SPEC explicitly excludes.
    return type(value) is int


def read_changes(records):
    """Validate ``changes``, collapse identical duplicates, keep first order.

    Duplicates are equal only when id, component, units and the dependency
    *set* agree; the same id with any other content is a conflict. The
    dependency list is kept as given here; planner.py compiles it into a
    set-based graph, so dependency order never leaks into the result.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        if not _is_id(row.get("id")) or not isinstance(row.get("component"), str) or not row["component"]:
            raise JournalError("invalid-change")
        if not _is_int(row.get("units")) or row["units"] < 1:
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on", [])
        if not isinstance(depends_on, list) or not all(_is_id(item) for item in depends_on):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        }
        identity = (change["component"], change["units"], frozenset(depends_on))
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = identity
            changes.append(change)
        elif previous != identity:
            raise JournalError("conflicting-change")
        # Identical duplicate: dropped, so it is accounted and graphed once.
    return changes


def read_applied(request):
    """Validate the caller-supplied persisted journal of applied change IDs.

    Missing means empty (SPEC default). Malformed input is ``invalid-change``;
    IDs unknown to the change set are caught in planner.py where the graph is
    built, keeping this layer free of graph knowledge.
    """
    applied = request.get("applied", [])
    if not isinstance(applied, list) or not all(_is_id(item) for item in applied):
        raise JournalError("invalid-change")
    return frozenset(applied)

planner.py.text:
"""Compose policy and journal data into a plan.

Import direction is fixed (SPEC line 3): this layer reads journal and policy,
never the reverse, and release.py only calls in here. Ordering happens after
journal validation/replay so the graph sees collapsed records, and the budget
check runs last because it is measured on the emitted set.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return every change ID in a deterministic dependency order.

    Edges point dependency -> dependent. Eligibility is decided among "/all"
    changes, not just unapplied ones, so ``plan`` and ``rollback`` share one
    order; a change whose dependency is already applied is still emitted in
    its own position rather than dropped from the sequence. Ready IDs are
    drained through a heap so ties break lexicographically regardless of
    input order. Any leftover node means a cycle; a dependency naming no
    record is caught before sorting starts.
    """
    known = {change["id"] for change in changes}
    dependents = {change["id"]: [] for change in changes}
    indegree = {}
    for change in changes:
        deps = set(change["depends_on"])
        missing = deps - known
        if missing:
            raise JournalError("unknown-dependency")
        indegree[change["id"]] = len(deps)
        for dep in deps:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for nxt in dependents[current]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(changes):
        # Cyclic nodes never reach indegree 0, so they never enter the output.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        action = request["action"]
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        units_by_id = {change["id"]: change["units"] for change in changes}
        if not applied <= units_by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if action == "rollback":
        # Reverse of the full order: dependents come down before their deps.
        # Already-applied entries are irrelevant here (all are applied), and
        # budget was validated but is not a cap for rollback.
        emitted = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Applied entries still satisfy dependencies but emit nothing, so they
        # neither appear in actions nor consume budget.
        emitted = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in emitted)
    try:
        check_budget(action, budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": emitted, "units": units}

